//! The runtime of a module inside the library that exports it: its threads, its private space,
//! and the services it registers when NAOqi loads it.

use super::{Session, SpaceNode};
use crate::{
    service, service_directory::LocalServiceDirectory, AnyObject, Error, Node, ObjectExt, Result,
};
use std::{
    future::Future,
    sync::{Mutex, OnceLock},
    time::Duration,
};
use tracing::{error, info, warn};

/// The definition of a module, generated by [`#[qi::module]`](macro@crate::module).
pub struct ModuleDef {
    /// The name of the module, the one hosts import it by.
    pub name: &'static str,
    /// The description of the module object.
    pub description: &'static str,
    /// The factories of the module.
    pub factories: &'static [FactoryDef],
    /// Creates the module object, whose methods are the functions and factories of the module.
    pub object: fn(Session) -> AnyObject,
    #[doc(hidden)]
    pub state: State,
}

/// A factory of a module.
#[derive(Debug, Clone, Copy)]
pub struct FactoryDef {
    /// The name of the factory, which is also the name of the service its object is registered
    /// as by `qilaunch -o module.Factory`.
    pub name: &'static str,
    /// Whether the object of the factory is registered as a service when NAOqi loads the
    /// library from its `autoload.ini`.
    pub autoload: bool,
}

/// The runtime state of a module, created on first use.
#[doc(hidden)]
#[derive(Default)]
pub struct State {
    runtime: OnceLock<tokio::runtime::Handle>,
    owned_runtime: Mutex<Option<tokio::runtime::Runtime>>,
    session: OnceLock<Session>,
    object: OnceLock<AnyObject>,
    private_space: tokio::sync::OnceCell<PrivateSpace>,
    autoloaded: Mutex<Vec<service::Id>>,
}

impl State {
    pub const fn new() -> Self {
        Self {
            runtime: OnceLock::new(),
            owned_runtime: Mutex::new(None),
            session: OnceLock::new(),
            object: OnceLock::new(),
            private_space: tokio::sync::OnceCell::const_new(),
            autoloaded: Mutex::new(Vec::new()),
        }
    }
}

/// The space a module hosts on the loopback interface, where its object is the service named
/// after the module, for its host to reach it.
struct PrivateSpace {
    _node: Node<LocalServiceDirectory>,
    endpoint: String,
}

impl ModuleDef {
    /// The session of the module, shared by all its members.
    pub fn session(&self) -> Session {
        self.state.session.get_or_init(Session::default).clone()
    }

    /// The module object, whose methods are the functions and factories of the module.
    pub fn object(&self) -> AnyObject {
        self.state
            .object
            .get_or_init(|| (self.object)(self.session()))
            .clone()
    }

    /// The threads of the module: a runtime of its own, independent of the one of its host,
    /// which is another copy of the runtime library (or none, for a C++ host).
    ///
    /// When it starts, the library is pinned in memory (its threads run until the process
    /// exits, even if the host unloads it), and the runtime is set to stop at the exit of the
    /// process, before the static destructors of the host (and of `libqi`) run.
    fn runtime(&'static self) -> &'static tokio::runtime::Handle {
        self.state.runtime.get_or_init(|| {
            init_logging();
            pin_library();
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .thread_name(format!("qi-module-{}", self.name))
                .enable_all()
                .build()
                .expect("the runtime of the module can be created");
            let handle = runtime.handle().clone();
            *self
                .state
                .owned_runtime
                .lock()
                .expect("lock is not poisoned") = Some(runtime);
            stop_at_exit(self);
            handle
        })
    }

    /// Stops the threads of the module, without waiting for them.
    fn stop_runtime(&self) {
        let runtime = self
            .state
            .owned_runtime
            .lock()
            .map(|mut runtime| runtime.take())
            .unwrap_or_default();
        if let Some(runtime) = runtime {
            runtime.shutdown_background();
        }
    }

    /// Runs a future on the runtime of the module and waits for its result, from any thread
    /// that is not one of the threads of the module.
    pub(super) fn block_on<F>(&'static self, future: F) -> F::Output
    where
        F: Future + Send + 'static,
        F::Output: Send + 'static,
    {
        let (sender, receiver) = std::sync::mpsc::sync_channel(1);
        self.runtime().spawn(async move {
            sender.send(future.await).ok();
        });
        receiver
            .recv()
            .expect("the tasks of the module run to completion")
    }

    /// Sets the URL of the space of the host, used by the session of the module unless it is
    /// already connected.
    pub fn set_space_url(&self, url: &str) {
        if !self.session().set_url(url.to_owned()) {
            warn!(
                module = self.name,
                url,
                connected_url = %self.session().url(),
                "the module is already connected to another space"
            );
        }
    }

    /// Sets an option of the module (see [`ModuleV1::set_option`](super::abi::ModuleV1::set_option));
    /// returns whether it is known and valid.
    pub fn set_option(&self, key: &str, value: &str) -> bool {
        match key {
            "space-url" => {
                self.set_space_url(value);
                true
            }
            "listen-url" => {
                self.session().set_listen_url(value.to_owned());
                true
            }
            "machine-id" => match value.parse() {
                Ok(id) => {
                    let set = crate::value::os::MachineId::set_local(id);
                    if !set {
                        warn!(
                            module = self.name,
                            machine_id = value,
                            "the machine identifier is already in use"
                        );
                    }
                    set
                }
                Err(_) => false,
            },
            _ => false,
        }
    }

    /// Starts the module for a host: hosts its private space if not done yet, and returns the
    /// URL of its endpoint.
    pub fn start(&'static self) -> Result<String> {
        self.block_on(async move {
            let space = self
                .state
                .private_space
                .get_or_try_init(|| self.host_private_space())
                .await?;
            Ok(space.endpoint.clone())
        })
    }

    async fn host_private_space(&'static self) -> Result<PrivateSpace> {
        let mut node = crate::node::init();
        node.add_service_object(self.name, self.object());
        node.bind("tcp://127.0.0.1:0".parse().expect("a valid address"));
        let node = node.host_space().start().await?;
        let endpoint = node
            .endpoints()
            .iter()
            .map(ToString::to_string)
            .find(|endpoint| endpoint.starts_with("tcp://"))
            .ok_or_else(|| Error::from("the private space of the module has no TCP endpoint"))?;
        info!(module = self.name, %endpoint, "module started");
        Ok(PrivateSpace {
            _node: node,
            endpoint,
        })
    }

    /// Registers the objects of the `autoload` factories as services of the space, in the
    /// background: what NAOqi expects from a library of its `autoload.ini`. The space is the one
    /// at `QI_URL`, else the local NAOqi; it is retried until it answers, NAOqi loading its
    /// modules before it accepts connections.
    pub fn autoload(&'static self) {
        let factories: Vec<_> = self.factories.iter().filter(|f| f.autoload).collect();
        let runtime = self.runtime();
        self.session().set_listen_url("tcp://0.0.0.0:0".to_owned());
        info!(
            module = self.name,
            url = %self.session().url(),
            services = ?factories.iter().map(|f| f.name).collect::<Vec<_>>(),
            "module loaded by NAOqi"
        );
        runtime.spawn(async move {
            let session = self.session();
            let node = session.node_with_retry(Duration::from_secs(1)).await;
            for factory in factories {
                match self.register_factory(node, factory.name).await {
                    Ok(id) => {
                        info!(module = self.name, service = factory.name, %id, "service registered");
                        self.state
                            .autoloaded
                            .lock()
                            .expect("lock is not poisoned")
                            .push(id);
                    }
                    Err(err) => error!(
                        module = self.name,
                        service = factory.name,
                        error = &err as &dyn std::error::Error,
                        "could not register the service"
                    ),
                }
            }
        });
    }

    async fn register_factory(&'static self, node: &SpaceNode, name: &str) -> Result<service::Id> {
        let object: AnyObject = self.object().call(name, ()).await?;
        node.register_service_object(name, object).await
    }

    /// Unregisters the services registered by [`ModuleDef::autoload`].
    pub fn close(&'static self) {
        let ids = std::mem::take(&mut *self.state.autoloaded.lock().expect("lock is not poisoned"));
        if ids.is_empty() {
            return;
        }
        let session = self.session();
        self.block_on(async move {
            let Ok(node) = session.node().await else {
                return;
            };
            for id in ids {
                let result =
                    tokio::time::timeout(Duration::from_secs(5), node.unregister_service(id)).await;
                if !matches!(result, Ok(Ok(()))) {
                    warn!(%id, "could not unregister the service");
                }
            }
        });
    }
}

/// The modules whose runtime stops at the exit of the process.
static STOP_AT_EXIT: Mutex<Vec<&'static ModuleDef>> = Mutex::new(Vec::new());

fn stop_at_exit(module: &'static ModuleDef) {
    extern "C" fn stop_modules() {
        let modules = STOP_AT_EXIT
            .lock()
            .map(|mut modules| std::mem::take(&mut *modules))
            .unwrap_or_default();
        for module in modules {
            module.stop_runtime();
        }
    }
    let mut modules = STOP_AT_EXIT.lock().expect("lock is not poisoned");
    if modules.is_empty() {
        // SAFETY: registering a function without argument, that does not unwind.
        #[allow(unsafe_code)]
        let _ = unsafe { libc::atexit(stop_modules) };
    }
    modules.push(module);
}

/// Keeps the library containing this code loaded until the process exits, as its threads run
/// its code: a host unloading it (`dlclose`) would unmap the code under them.
#[allow(unsafe_code)]
fn pin_library() {
    static ANCHOR: u8 = 0;
    // SAFETY: `dladdr` reads the loader's tables for an address of this library, and `dlopen`
    // with `RTLD_NOLOAD` only adds a reference (made permanent by `RTLD_NODELETE`) to the
    // already loaded library, running no initializer.
    unsafe {
        let mut info: libc::Dl_info = std::mem::zeroed();
        if libc::dladdr(std::ptr::from_ref(&ANCHOR).cast(), &mut info) != 0
            && !info.dli_fname.is_null()
        {
            let _handle = libc::dlopen(
                info.dli_fname,
                libc::RTLD_NOW | libc::RTLD_NOLOAD | libc::RTLD_NODELETE,
            );
        }
    }
}

/// Sends the traces of the module to the standard error, filtered by `QI_MODULE_LOG` (with the
/// syntax of `RUST_LOG`; default: warnings, and information from this module system). The
/// library has its own copy of the tracing library, and its host no subscriber for it.
fn init_logging() {
    use tracing_subscriber::{filter::EnvFilter, fmt};
    let filter = std::env::var("QI_MODULE_LOG")
        .ok()
        .and_then(|filter| EnvFilter::try_new(filter).ok())
        .unwrap_or_else(|| EnvFilter::new("warn,qi::module=info"));
    fmt()
        .with_env_filter(filter)
        .with_writer(std::io::stderr)
        .with_target(true)
        .try_init()
        .ok();
}
